measures.expression:
CALCULATE(
    COUNTROWS(gold_recommendations),
    gold_recommendations[priority_label] IN {"Critical", "High"}
)

// Caption only when there is no ACTIONABLE install-solar row in the current
// view; otherwise an empty string so the overlay card shows nothing (no dash).
VAR _n =
    CALCULATE (
        COUNTROWS ( gold_recommendations ),
        gold_recommendations[action_type] = "INSTALL_SOLAR",
        gold_recommendations[priority_label] <> "INFORMATIONAL"
    )
RETURN
    IF ( ISBLANK ( _n ) || _n = 0, "No install-solar opportunity for the current selection.", "" )

// Bu hafta tüketimi / geçen hafta tüketimi karşılaştırması (%)
// Pozitif = artış, Negatif = azalış
// FORMAT: "0.0" (×100 yapılmış)
VAR _thisWeek = [Current Week kWh v14]
VAR _lastWeek = [Last Week kWh v14]
RETURN
DIVIDE(_thisWeek - _lastWeek, _lastWeek, BLANK()) * 100

// Geçen haftanın enerji maliyeti (EUR)
CALCULATE(
    [Total Energy Cost EUR],
    '''Date'''[IsLastWeek] = TRUE()
)

// Geçen haftanın CO₂ emisyonu (metrik ton)
CALCULATE(
    [Total CO2 Emissions tCO2],
    '''Date'''[IsLastWeek] = TRUE()
)

// Geçen hafta maksimum güç talebi (kW)
CALCULATE(
    [Peak Demand kW],
    '''Date'''[IsLastWeek] = TRUE()
)

// Geçen hafta güneş enerjisi üretimi
CALCULATE(
    [Total Solar Generated kWh],
    '''Date'''[IsLastWeek] = TRUE()
)

// Bu ay / geçen ay tüketim değişimi (%)
// Not: Ay tamamlanmamışsa eksik gün sayısı dikkate alınmaz — tam ay için kullan
// FORMAT: "0.0"
VAR _thisMonth = [Current Month kWh v14]
VAR _lastMonth = [Last Month kWh v14]
RETURN
DIVIDE(_thisMonth - _lastMonth, _lastMonth, BLANK()) * 100

// Geçen ayın enerji maliyeti
CALCULATE(
    [Total Energy Cost EUR],
    '''Date'''[IsLastMonth] = TRUE()
)

// Geçen ayın CO₂ emisyonu
CALCULATE(
    [Total CO2 Emissions tCO2],
    '''Date'''[IsLastMonth] = TRUE()
)

// Geçen ayın pik güç talebi
CALCULATE(
    [Peak Demand kW],
    '''Date'''[IsLastMonth] = TRUE()
)

// Geçen ayın güneş üretimi
CALCULATE(
    [Total Solar Generated kWh],
    '''Date'''[IsLastMonth] = TRUE()
)

// Son 7 günün tüketimi — rolling pencere (bugün dahil)
// Slicer'dan bağımsız — her zaman son 7 günü gösterir
VAR _maxDate = CALCULATE(MAX(gold_kpi_daily[date]), REMOVEFILTERS('''Date'''))
RETURN
CALCULATE(
    [Total Consumption kWh],
    REMOVEFILTERS('''Date'''),
    DATESINPERIOD(gold_kpi_daily[date], _maxDate, -7, DAY)
)

ROUND (
    AVERAGEX (
        FILTER (
            gold_anomaly_log,
            gold_anomaly_log[is_resolved] = FALSE
        ),
        DATEDIFF ( gold_anomaly_log[detected_date], TODAY (), DAY )
    ),
    0
)

CALCULATE (
    COUNTROWS ( gold_anomaly_log ),
    gold_anomaly_log[is_resolved] = FALSE,
    gold_anomaly_log[severity] IN { "CRITICAL", "HIGH" }
)

// Uppercase fix — v11 sonrası "CRITICAL"
CALCULATE (
    COUNTROWS ( gold_anomaly_log ),
    gold_anomaly_log[severity] = "CRITICAL",
    gold_anomaly_log[is_resolved] = FALSE
)

// Generation-weighted Performance Ratio (energy basis).
// Each day's PR is weighted by that day's generation, so small or low-sun
// systems cannot inflate the portfolio figure. Daily PR is already energy-basis
// and clamped at 0.95 in gold. Days with no valid PR (no PV, or low-sun gated)
// drop out of BOTH numerator and denominator so they neither lift nor dilute.
VAR _num =
    SUMX ( gold_kpi_daily, gold_kpi_daily[solar_generated_kwh] * gold_kpi_daily[avg_solar_pr] )
VAR _den =
    SUMX (
        FILTER ( gold_kpi_daily, NOT ISBLANK ( gold_kpi_daily[avg_solar_pr] ) ),
        gold_kpi_daily[solar_generated_kwh]
    )
RETURN
    DIVIDE ( _num, _den ) * 100

CALCULATE (
    COUNTROWS ( gold_anomaly_log ),
    REMOVEFILTERS ( ),
    gold_anomaly_log[is_resolved] = FALSE ( ),
    UPPER ( gold_anomaly_log[severity] ) IN { "HIGH", "CRITICAL" }
) + 0

// Annual generation a building would gain at the healthy target PR.
// Target PR 0.80. Buildings at or above target return blank. Self-annualizing
// via solar-day count so the date slicer does not distort the yearly figure.
VAR _prTarget = 0.80
VAR _pr = DIVIDE ( [Avg Solar PR Pct], 100 )
VAR _days = CALCULATE ( DISTINCTCOUNT ( gold_kpi_daily[date] ), gold_kpi_daily[solar_generated_kwh] > 0 )
VAR _years = DIVIDE ( _days, 365.0 )
VAR _genAnnual = DIVIDE ( [Total Solar Generated kWh], _years )
VAR _uplift = MAX ( 0, DIVIDE ( _prTarget - _pr, _pr ) )
RETURN IF ( _pr > 0 && _uplift > 0, _genAnnual * _uplift, BLANK () )

// Value of the lost generation at the building's own effective solar tariff
// (platform savings per self-consumed kWh). Per-building, no hardcoded price.
VAR _lostKwh = [PV Underperf Lost Gen kWh (Est)]
VAR _tariff = DIVIDE ( SUM ( gold_kpi_daily[estimated_savings_eur] ), SUM ( gold_kpi_daily[solar_self_consumed_kwh] ) )
RETURN IF ( NOT ISBLANK ( _lostKwh ) && _lostKwh > 0, _lostKwh * _tariff, BLANK () )

// Payback of the building's installed (active / Measured) strategy.
// Portfolio view averages the installed paybacks across buildings.
CALCULATE (
    AVERAGE ( gold_battery_simulation[payback_years] ),
    gold_battery_simulation[is_active_strategy] = "True"
)
